def snippet(kind, fname, tests, *, secs=2., total=10., setup=(), nonce:str=None) -> str:
    "Build a standalone kernel check that prints one public JSON result with `nonce`."
    if kind not in ('assert', 'cell'): raise ValueError("kind must be 'assert' or 'cell'")
    dependencies = [stop, adict, AttrDict, time_limit, public]
    runners = [safe_test, run_asserts] if kind == 'assert' else [run_cells]
    data = json.dumps(dict(fname=fname, tests=tests, secs=secs, total=total, setup=list(setup), safe_names=SAFE_NAMES, nonce=nonce))
    parts = [
        'import ast, builtins, ctypes, io, json, signal, threading, time',
        'from contextlib import contextmanager, redirect_stdout, redirect_stderr',
        f'data = json.loads({data!r})',
        'SAFE_NAMES = tuple(data["safe_names"])',
        'SAFE_BUILTINS = {n: getattr(builtins, n) for n in SAFE_NAMES if hasattr(builtins, n)}',
        'SAFE_NODES = (' + ', '.join(f'ast.{node.__name__}' for node in SAFE_NODES) + ',)',
        f'TEST_SECONDS = {TEST_SECONDS!r}',
        *(inspect.getsource(obj) for obj in dependencies),
        'class Report(AttrDict):\n' + inspect.getsource(Report.passed.fget),
        *(inspect.getsource(obj) for obj in runners),
    ]
    if kind == 'assert':
        parts.append('result = run_asserts(_ns.get(data["fname"]), data["fname"], data["tests"], secs=data["secs"], total=data["total"])')
    else:
        parts.append('result = run_cells(data["tests"], _ns, setup=data["setup"], secs=data["secs"], total=data["total"])')
    parts.append('print(json.dumps({"nonce": data["nonce"], **public(result)}))')
    return f'exec({chr(10).join(parts)!r}, {{"_ns": globals()}})'


# %% ../nbs/06_check.ipynb #0b115444
def parse(text, nonce:str=None) -> dict:
    "Read the last public check JSON line, or return a missing-result error. With `nonce`, only a line with that nonce counts."
    for line in reversed(text.splitlines()):
        try: result = json.loads(line)
        except (ValueError, TypeError): continue
        if nonce is not None and not (isinstance(result, dict) and result.get('nonce') == nonce): continue
        if (isinstance(result, dict) and result.get('v') == 1
            and isinstance(result.get('found'), bool) and isinstance(result.get('timeout'), bool)
            and isinstance(result.get('checks'), list)): return {k: v for k, v in result.items() if k != 'nonce'}
        return {'error': 'no check result'}
    return {'error': 'no check result'}

# %% ../nbs/06_check.ipynb #b7c1a002
def _guard(tmp, unix=False):
    "Add an audit hook that refuses the network, ctypes libraries, new processes, and file changes outside the folder `tmp`; with `unix`, allow a local socket pair."
    import os, sys, socket, ctypes
    writes = os.O_WRONLY | os.O_RDWR | os.O_APPEND | os.O_CREAT | os.O_TRUNC
    def outside(p): return isinstance(p, (str, bytes, os.PathLike)) and not os.path.realpath(os.fsdecode(p)).startswith(tmp + os.sep)
    def hook(event, args):
        if event.startswith(('ctypes.dlopen', 'ctypes.dlsym')):
            raise PermissionError(f'{event} is not allowed')
        if unix and event == 'socket.__new__' and args[1] == socket.AF_UNIX: return
        if event.startswith(('socket.', 'os.exec', 'os.posix_spawn', 'os.fork')) or event in ('subprocess.Popen', 'os.system'):
            raise PermissionError(f'{event} is not allowed')
        if event == 'open' and ((isinstance(args[1], str) and any(m in args[1] for m in 'wax+')) or args[2] & writes) and outside(args[0]):
            raise PermissionError(f'writing to {args[0]} is not allowed')
        if event in ('os.remove', 'os.rename', 'os.rmdir', 'os.mkdir', 'os.truncate', 'os.symlink', 'os.link', 'shutil.rmtree') and any(map(outside, args)):
            raise PermissionError(f'{event} outside the work folder is not allowed')
    ctypes.pythonapi.PyThreadState_SetAsyncExc   # the timer needs this symbol: look it up now, before the hook
    sys.addaudithook(hook)

# %% ../nbs/06_check.ipynb #b7c1a004
SANDBOX_EXEC = '/usr/bin/sandbox-exec'
SANDBOX_PROFILE = """(version 1)
(allow default)
(deny network*)
(deny process-fork)
(deny file-write*)
(allow file-write* (subpath (param "TMP")) (literal "/dev/null"))"""
FILE_LIMIT = 10 * 2**20   # bytes: the largest file that the process can write

# %% ../nbs/06_check.ipynb #b7c1a006
def _limits(total) -> str:
    "Code that limits the process to `total + 1` s of CPU time and to files of 10 MB, when the system has the `resource` module."
    cpu = int(total) + 1
    return (f'try:\n    import resource\n    resource.setrlimit(resource.RLIMIT_CPU, ({cpu}, {cpu + 1}))\n'
            f'    resource.setrlimit(resource.RLIMIT_FSIZE, ({FILE_LIMIT}, {FILE_LIMIT}))\n    del resource\nexcept ImportError: pass\n')

# %% ../nbs/06_check.ipynb #b7c1a013
def _split_future(source) -> tuple:
    "The docstring and the `from __future__` imports at the start of `source`, and the code after them."
    try: tree = ast.parse(source)
    except (SyntaxError, ValueError): return '', source
    n = 0
    for i, s in enumerate(tree.body):
        if isinstance(s, ast.ImportFrom) and s.module == '__future__': n = s.end_lineno
        elif not (i == 0 and isinstance(s, ast.Expr) and isinstance(s.value, ast.Constant) and isinstance(s.value.value, str)): break
    lines = source.splitlines(keepends=True)
    return ''.join(lines[:n]), ''.join(lines[n:])

# %% ../nbs/06_check.ipynb #b7c1a008
def run_isolated(kind, fname, source, tests, *, total=10., setup=(), sandbox=True, python=None, unix=False) -> dict:
    "Run `source` and its checks in a closed process with no network, using `python` (default `sys.executable`); with `unix`, it can use a local socket pair."
    import tempfile
    nonce, (head, body) = os.urandom(8).hex(), _split_future(source)
    with tempfile.TemporaryDirectory() as tmp:
        tmp, cmd, pre = os.path.realpath(tmp), [python or sys.executable, '-I', '-B'], _limits(total)
        if sandbox:
            pre += f'{inspect.getsource(_guard)}\n_guard({tmp!r}, {unix!r})\ndel _guard\n'
            if sys.platform == 'darwin' and os.path.exists(SANDBOX_EXEC): cmd = [SANDBOX_EXEC, '-p', SANDBOX_PROFILE, '-D', f'TMP={tmp}', *cmd]
        code = f'{head}\n{pre}{body}\n' + snippet(kind, fname, tests, total=total, setup=setup, nonce=nonce)
        try:
            with subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, cwd=tmp,
                                  env={'PATH': os.defpath, 'HOME': tmp}, start_new_session=True) as p:
                try: out, _ = p.communicate(code, timeout=total + 2)
                except subprocess.TimeoutExpired:   # stop the whole group: a process that the code started can keep the output open
                    try: os.killpg(p.pid, signal.SIGKILL)
                    except (AttributeError, ProcessLookupError): p.kill()
                    p.wait()
                    return {'timeout': True}
        except OSError: return {'error': 'no check result'}   # `python` cannot start
    if -p.returncode in (getattr(signal, 'SIGXCPU', None), getattr(signal, 'SIGKILL', None)): return {'timeout': True}
    return {'error': 'no check result'} if p.returncode < 0 else parse(out, nonce)
